<script lang="ts">import {auth} from '$lib/api';import TopNav from '$lib/components/TopNav.svelte';let email=$state(''),message=$state(''),error=$state(''),loading=$state(false);async function submit(){if(!email){error='Enter your email address.';return}loading=true;error='';message='';try{await auth.forgotPassword(email);message='If an account exists for this email, we have sent a password reset link.'}catch(e){error=e instanceof Error?e.message:'Unable to request a reset link.'}finally{loading=false}}</script><svelte:head><title>Forgot Password · RegenFeed</title></svelte:head><TopNav/><main class="stitch-auth stitch-register"><form class="stitch-card" onsubmit={(e)=>{e.preventDefault();submit()}}><div class="stitch-heading"><h1>Reset your password</h1><p>We will send a secure reset link to your email.</p></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if message}<p class="success" role="status">{message}</p>{/if}<label>Email Address<div class="stitch-input"><input bind:value={email} type="email" autocomplete="email" placeholder="you@example.com" required /></div></label><button class="stitch-button" disabled={loading}>{loading?'Sending…':'Send reset link'} <i class="fa-solid fa-arrow-right"></i></button><p class="stitch-switch"><a href="/auth/login">Back to login</a></p></form></main>
